INSERT INTO lpm_time_assumptions (id, project_id, plan_id, axis_id, projection_id, statement, assumption_type, confidence, source, rationale, value)
VALUES ('4066dbfb-93af-57ef-a769-ed138548944f', '371fce26-d1f3-439b-95df-0a0e38b8a824', '57b98764-f4ca-5559-ae79-578f7555edd2', NULL, NULL, 'Each stage takes its time in equal parts from the school subjects its strand is associated with in the source LPM, listed on this page. Science is counted as biology. A share of a subject that has no hours in a grade band moves to the other subjects of that stage.', 'derived', 'low', 'Strand field associatedDomains of the source LPM (oe-interdisciplinary-k12). Equal weights are an AI-drafted rule.', 'The split is the largest judgement in this plan. It rests on the strand field associatedDomains of the source LPM, and the equal parts are an AI-drafted rule with no source. Stages within a strand may lean one way or the other. Argue it stage by stage and change it on this page.', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_time_assumptions (id, project_id, plan_id, axis_id, projection_id, statement, assumption_type, confidence, source, rationale, value)
VALUES ('e3cc5019-c61c-57ae-8dda-d7dfc2f5b289', '371fce26-d1f3-439b-95df-0a0e38b8a824', '57b98764-f4ca-5559-ae79-578f7555edd2', NULL, NULL, 'The space takes the same total evolution hours as the one-subject plan with the same pattern. The split decides which subject gives them.', 'derived', 'medium', 'Design note 2026-10-25, section 5.12.', 'This keeps the comparison with a space that lives in biology alone fair on total hours. The alternative is that every subject gives the same share of its own hours, which the page offers as a setting.', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_time_plans (id, project_id, axis_id, name, summary, kind, parameters, status)
VALUES ('ec5fe878-e0e7-548e-9d1d-d80604ce9a87', '371fce26-d1f3-439b-95df-0a0e38b8a824', '61b50773-f946-5657-a957-1faf4e02f3b7', 'Three subjects, same hours: stages in sequence, in dependency order', 'The same pattern and the same total evolution hours as the matching one-subject starter plan. The hours come from biology, social studies and computer science in the split shown on this page. The split is an AI-drafted placeholder, unreviewed, and the plan makes no recommendation.', 'planned', '{"preset":"sequenced","share":{"low":0.1,"high":0.3},"reinforcing_share":0.15,"sequence_order":"dependency","hosts":{"basis":"matched-hours","split":{"04d57493-ac2f-5ec6-a1ba-0596eae3158a":{"biology":0.5,"social-studies":0.5},"31b2be29-7a8c-5f98-a447-55ecf57f1ff9":{"biology":0.5,"social-studies":0.5},"396e3dd9-4f22-5160-b6c7-3752caefa1b8":{"biology":0.5,"social-studies":0.5},"3a112595-4435-5db0-950d-ca7c6da5160d":{"biology":0.5,"social-studies":0.5},"5d938d91-e81b-516c-ba58-a234b6d5559f":{"biology":0.5,"social-studies":0.5},"6315aad7-35b7-52dc-9dd2-1b82d707a768":{"biology":0.5,"social-studies":0.5},"6f04ee30-2be3-537b-9d0e-b339d9fed79c":{"biology":0.5,"social-studies":0.5},"8363df74-ecd8-54e9-82f1-e93623f9995c":{"biology":0.5,"social-studies":0.5},"9fc65a59-5de1-51ad-ad30-a9c0faca177a":{"social-studies":0.5,"computer-science":0.5},"a1bc92d8-3730-53b8-a059-f3999e4387cf":{"social-studies":0.5,"computer-science":0.5},"a64224d1-ac36-5b1c-b475-3c5af3aa4656":{"biology":0.5,"social-studies":0.5},"ad0173a4-5c64-5d05-96ac-2b61810c4153":{"social-studies":0.5,"computer-science":0.5},"ba60a3be-0135-5b53-b88f-a7aecfe0ed96":{"biology":0.5,"social-studies":0.5},"d2dc3119-7af8-55d8-8bfe-b63a4ec56acb":{"biology":0.5,"social-studies":0.5},"db1fca08-0dcf-5910-a3df-2de902e8630a":{"biology":0.5,"social-studies":0.5},"e820dc2d-9317-57d1-8475-22a701fc486a":{"social-studies":0.5,"computer-science":0.5}}}}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
