INSERT INTO lpm_time_assumptions (id, project_id, plan_id, axis_id, projection_id, statement, assumption_type, confidence, source, rationale, value)
VALUES ('656a1106-8de1-5d14-87a2-961545db5dd2', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'ec5fe878-e0e7-548e-9d1d-d80604ce9a87', NULL, NULL, 'Each stage takes its time in equal parts from the school subjects its strand is associated with in the source LPM, listed on this page. Science is counted as biology. A share of a subject that has no hours in a grade band moves to the other subjects of that stage.', 'derived', 'low', 'Strand field associatedDomains of the source LPM (oe-interdisciplinary-k12). Equal weights are an AI-drafted rule.', 'The split is the largest judgement in this plan. It rests on the strand field associatedDomains of the source LPM, and the equal parts are an AI-drafted rule with no source. Stages within a strand may lean one way or the other. Argue it stage by stage and change it on this page.', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_time_assumptions (id, project_id, plan_id, axis_id, projection_id, statement, assumption_type, confidence, source, rationale, value)
VALUES ('9b0ba2bb-d242-5901-8a65-53707c0099c9', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'ec5fe878-e0e7-548e-9d1d-d80604ce9a87', NULL, NULL, 'The space takes the same total evolution hours as the one-subject plan with the same pattern. The split decides which subject gives them.', 'derived', 'medium', 'Design note 2026-10-25, section 5.12.', 'This keeps the comparison with a space that lives in biology alone fair on total hours. The alternative is that every subject gives the same share of its own hours, which the page offers as a setting.', NULL) ON CONFLICT (id) DO NOTHING;

